"""Independently authored problems; authentic adaptations preserve scan provenance."""
from pathlib import Path
import json,hashlib,math
B=Path(__file__).resolve().parent;R=B.parent
questions=[]
def q(title,stem,solution,expected,origin='Original mathematical examination-style problem',check=None,options=None,answer=None):
    z=dict(id=f'ARR_{len(questions)+1:02}',title=title,stem=stem,solution=solution,expected=str(expected),origin=origin,difficulty='Medium–Hard')
    if check:z['check']=check
    if options:z.update(options=options,answer=answer)
    questions.append(z)
q('Stable insert and erase in one buffer','An array of length 17 and capacity 24 receives a stable insertion at rank 6, then a stable deletion at rank 10. Count old-slot shifts and new-value writes separately. Do not clear unused reference slots.',r'Insertion shifts $17-6=11$ old slots and writes one new value. The length becomes 18. Deletion then shifts $18-10-1=7$ old slots. Thus there are 18 shifts and 19 element writes. Using the original length for deletion gives an off-by-one error; counting a metadata update as an element write changes the specified model.','18 shifts; 19 writes',check=dict(kind='insertdelete',n=17,i=6,j=10))
q('Front insertion followed by front removal','Start with an empty preallocated array. Insert 40 values at the front, then remove all 40 from the front. Preserve order. How many old-slot shifts occur?',r'Insertion shifts $\sum_{j=0}^{39}j=780$. Deletion shifts $39+38+\cdots+0=780$. Total shifts are 1560. Forty new-value writes are additional if total element writes are requested. Neither phase benefits from spare capacity: shifting follows the ordering contract.','1560',check=dict(kind='front',m=40))
q('Expected insertion work with biased positions','A length-12 array has spare capacity. With probability one half insert at rank zero; otherwise choose uniformly among ranks 1 through 12. Find expected old-slot shifts.',r'Front insertion costs 12. In the other branch costs are 11 through 0, with mean $11/2$. Therefore $E[S]=12/2+(11/2)/2=35/4$. The answer is not 6 because all 13 positions are not equally likely. Expected cost does not establish a worst-case or amortized bound.','35/4')
q('Insertion loop counterexample','For `[3,5,7,11]`, insert 2 at rank 1 by looping `j=1,2,3` with `A[j+1]=A[j]`, then writing `A[1]=2`. Give the actual result and the correct result.',r'The first copy overwrites 7 with 5; later copies read the overwritten 5, so the actual live array is `[3,2,5,5,5]`. The required stable result is `[3,2,5,7,11]`. Processing right to left preserves each unread source. A proof must describe which old values remain available, not only the final length.','[3,2,5,5,5] versus [3,2,5,7,11]',origin='Independent reconstruction of Oxford B16 §3.1 shift invariant')
q('Removing order from the contract','A mutable array is used as an unordered bag. You know rank 3 in a 1000-element bag. Explain an $O(1)$ deletion and why it does not implement stable sequence deletion.',r'Assign the last live value to rank 3 and decrement length. With the index supplied, this uses one payload assignment plus metadata; clearing the vacated slot may add a write. It moves the last element before many former neighbors, violating stable order. Searching for a target value still costs linear time without another index.','Swap-with-last changes the ordering contract')
q('Overlapping range movement','Move `A[2..7]` to `A[4..9]` without temporary storage. Which direction is safe, and what invariant proves it?',r'The destination lies to the right and overlaps the source, so copy indices 7 down to 2. Each unread source lies at or left of the current source and is not overwritten by the larger destination index. Ascending order would overwrite A[4] before it is read. For a destination to the left, ascending order is safe. There are exactly six slot copies.','Right-to-left, six copies')
q('Doubling at a nonpower length','An append-only array starts at capacity 1. After 100 appends, count resize copies, new-slot writes, final capacity, and worst individual append cost in the one-write-per-copy model.',r'Final capacity is 128. Resize copies total $1+2+4+\cdots+64=127$. There are 100 new-slot writes, so total is 227. The 65th append costs 65 element writes; this is the largest operation within the first 100 appends. The final append need not be the worst.','127 copies; 227 writes; capacity 128; worst 65',check=dict(kind='doubling',m=100))
q('Exact growth factor three','Start at capacity 2, triple whenever full, and append 55 values. Find final capacity and total old-slot copies.',r'Capacities are 2, 6, 18, 54, 162; the 55th append triggers the last growth. Copies are $2+6+18+54=80$. Fifty-five new-slot writes yield 135 total writes. Formula $(162-2)/(3-1)=80$ agrees with the trace. Applying a doubling formula would be incorrect.','162; 80 copies',check=dict(kind='growth',m=55,c0=2,g=3))
q('Fixed additive growth','Start at capacity 10 and grow by 10 when full. Append 101 values. Count copied slots.',r'Ten growth events copy buffers of size 10 through 100. Therefore copies are $10(1+\cdots+10)=550$. The final capacity is 110. Including appended values gives 651 writes. A constant capacity increment does not imply constant amortized work.','550',check=dict(kind='additive',m=101,h=10))
q('Sublinear capacity increment','Grow a full buffer of capacity $C$ by approximately $\sqrt C$ slots. Derive the order of total copy work needed to reach length $N$. Ignore rounding for the asymptotic derivation.',r'At capacity scale C, one resize pays C copies and supplies about $\sqrt C$ future append positions. Thus the local cost per new slot is about $\sqrt C$. Summing this scale over positions up to N gives $\Theta(\int_1^N\sqrt x\,dx)=\Theta(N^{3/2})$. A scale argument also proves the lower bound: within the last constant fraction of N, each growth adds at most $O(\sqrt N)$ slots and copies $\Omega(N)$ slots, forcing $\Omega(\sqrt N)$ such events.','Theta(N^(3/2))')
q('The initial potential term','Use $\Phi=2n-C$ for capacity-one doubling from an empty array. Is the assertion “total actual cost is at most $3m$ because $\Phi_0=0$” correct?',r'The conclusion can hold, but the supplied proof is wrong: $\Phi_0=-1$. Telescoping gives $\sum c_i=\sum\hat c_i+\Phi_0-\Phi_m=3m-1-\Phi_m$ when every append is charged three. After a nonempty state the potential is nonnegative. Shift the potential by one or isolate the first operation to meet the usual nonnegative-potential convention.','Conclusion may hold; Phi0 is −1')
q('Amortized versus worst case','Select the correct claim for doubling arrays under append-only workloads and constant slot-copy cost.',r'A full buffer of length n must copy n slots, so a single append can take linear time. Across any m appends from an empty structure, geometric sums give linear total work, hence constant amortized cost. This uses deterministic accounting, not random inputs. Real-time latency constraints cannot be inferred from amortization alone.','Option 3',options=['Every append has constant worst-case time.','Constant amortized time requires random inputs.','Append is amortized constant but can be linear individually.','Amortization removes all stable insertion shifts.'],answer=3,origin='Independent reconstruction of Princeton COS226 resizing distinction')
q('Quarter-full contraction accounting','A buffer has length 17 and capacity 64. Deleting its last element triggers half-capacity contraction at one quarter full. Charge one deletion plus live-slot copies. Compute actual cost, potential change, and amortized cost.',r'After deletion n=16 and capacity becomes 32. Actual cost is $1+16=17$. Before deletion the sparse-branch potential is $32-17=15$; afterward it is zero. Thus amortized cost is $17-15=2$. Clearing a reference slot or allocation work would require an adjusted actual-cost convention.','17; −15; 2',check=dict(kind='shrink',C=64))
q('Constructing a thrashing sequence','A full capacity-1024 buffer doubles on append and halves as soon as deletion leaves it half full. Show a repeating two-operation workload and its copy cost per repetition.',r'Append at length 1024 copies 1024 slots and reaches length 1025, capacity 2048. Delete the last value; length becomes 1024 and contraction copies 1024 slots into capacity 1024. The original state returns. Each repetition copies 2048 slots for only two updates. A quarter-full threshold avoids this immediate reversal.','2048 copies per append/delete pair')
q('Middle insertion with geometric resizing','Perform m stable front insertions into a doubling array from empty. Give total asymptotic work and explain why constant amortized append analysis is insufficient.',r'Shifts alone total $m(m-1)/2=\Theta(m^2)$. Resizing adds only $O(m)$ copied slots. Therefore total work is quadratic. The append proof accounts for capacity expansion, not movement required by arbitrary insertion positions. Combining two costs means adding them, not replacing the larger with the smaller.','Theta(m²)')
q('Peak memory during growth','A full array of capacity 4096 and eight-byte slots doubles. Allocation retains the old buffer until copying finishes. Ignore metadata. What is peak slot-storage memory?',r'Old storage is $4096\cdot8$ bytes; new storage is $8192\cdot8$ bytes. Simultaneous allocation requires $(4096+8192)8=98304$ bytes, or 96 KiB. Final storage alone is 64 KiB. A realloc implementation might behave differently; the stated separate-buffer model controls the answer.','98304 bytes',check=dict(kind='peak',C=4096,b=8,g=2))
q('Half-full is not half the memory','After doubling a full capacity-C array and appending one element, derive unused slots and unused fraction of allocated slots.',r'Capacity is 2C and length is C+1, so unused slots are C−1. Their fraction is $(C-1)/(2C)$, approaching but not exactly one half. Slack relative to live slots is $(C-1)/(C+1)$, a different denominator. At C=8 the unused fraction is 7/16.','(C−1)/(2C)')
q('Tail pointer and removal','An acyclic singly linked list stores head, tail, and size. For n>1, what is the worst-case time to remove tail while preserving node identities? Explain why caching the second-last node once is insufficient for repeated removal.',r'Tail has no back pointer; its predecessor must be found by a head traversal, costing linear time. A cached second-last handle permits one removal, but after it becomes tail the next predecessor is unknown. Maintaining that extra handle through repeated removals again needs traversal unless a richer structure stores predecessor information.','Theta(n)',origin='Independent reconstruction of Berkeley CS61B Chapter 5 tail-removal exercise')
q('Singly linked insertion order','Given P→Q and a fresh node X, execute `P.next=X; X.next=P.next`. Determine the resulting local links and repair the code.',r'After the first assignment P.next is X. The second makes X.next equal X, creating a self-cycle; Q is no longer reachable through P. Correct code first assigns X.next=Q (or the saved old P.next), then P.next=X. The lost source link is the same non-overwrite issue seen in array shifts.','P→X→X; initialize successor first')
q('Deleting the only real node','A list uses a head sentinel S, tail pointer T, and cached size. Its only real node is X. Define a convention for empty tail and list the metadata and link updates after deleting X.',r'Choose empty tail T=S. Save X.next=null, set S.next=null, set T=S, decrement size to zero, and release detached X. The postcondition includes both reachability and metadata. Keeping T=X leaves a dangling handle after release. A convention T=null is also valid if all operations use it consistently.','S.next=null; T=S; size=0')
q('Node-only deletion counterexample','A singly linked list A→B→C stores external handles to all nodes. Why is replacing B.value with C.value and bypassing C not a valid implementation of deleting the object B?',r'The operation leaves the object B allocated and linked; it changes its payload. It removes C and invalidates the external C handle. The value sequence can match deletion of B, but object identity and handle validity do not. At a tail there is no successor to copy. The contract must distinguish deleting a value position from deleting an object.','Value-sequence equivalence does not preserve node identity')
q('List invariant with a stale size','A list has seven reachable real nodes but cached size six. `get(i)` rejects i>=size. Is the defect merely a performance problem?',r'No. Retrieval at the valid logical last rank 6 is incorrectly rejected. The representation invariant equating cached size with reachable real-node count is broken, so interface behavior is incorrect. Recomputing size on every call can mask the metadata defect but changes costs and does not repair mutation logic.','Correctness defect')
q('Four insertion writes','In a circular doubly linked list, insert X between adjacent P and Q. Count required link-field writes, and distinguish insertion from unlinking X.',r'Initialize X.prev=P and X.next=Q, then set P.next=X and Q.prev=X: four writes. To unlink a known X, reconnect P.next=Q and Q.prev=P: two required external-link writes. Clearing X.prev and X.next adds two optional writes. A size increment or decrement is a separate metadata write.','4 for insertion; 2 for unlink')
q('Range splicing and cached size','Move a known consecutive range of 70 nodes between circular doubly linked lists. Endpoints and destination neighbors are supplied, but range length is not supplied to the operation. Each list caches size. Is the entire operation constant time?',r'Six boundary-link writes suffice for the splice: two close the old gap and four connect the range at its new location. However, updating both sizes requires the moved length. Discovering it from endpoints requires traversing the range, costing Theta(70) for this instance and Theta(k) generally. If k is supplied and trusted, this additional traversal disappears.','Rewiring constant; full operation Theta(k)')
q('Sentinel traversal termination','A circular doubly linked list has sentinel S and three real nodes. A scan stops only at null. What occurs, and how should the scan stop?',r'No next link is null: the last real node returns to S, which returns to the first node. The scan loops forever and may process the sentinel as data. Start at S.next and stop when the cursor equals S. Node identity is the stopping criterion. The empty list then terminates immediately because S.next=S.','Stop at sentinel identity')
q('Reversal write count','Reverse a 19-node acyclic singly linked list by the three-handle iterative algorithm. Count next-field writes and auxiliary live handles.',r'Every iteration writes cur.next once, including the original head’s null successor. Thus there are 19 next-field writes. Prev, cur, and saved nxt are a constant number of handles independent of length. Head and optional tail metadata updates are additional. Reversal does not allocate 19 replacement nodes.','19; constant handles',check=dict(kind='reverse',n=19))
q('A broken reversal loop','After `cur.next=prev; prev=cur`, a programmer sets `cur=cur.next` rather than a saved old successor. Trace the first iteration for A→B→C.',r'Initially prev=null and cur=A. Writing A.next=null destroys the link through which B would be reached. Then prev=A and cur=A.next=null; the loop ends with B and C absent from the returned prefix. Save nxt=B before rewriting A.next. The invariant must keep the untouched suffix reachable.','Returns only A and loses the suffix')
q('Recursion and storage','A routine recursively calls itself on next, then prints the current value, without modifying links. For n nodes, give output order, link-write count, and auxiliary space.',r'Calls reach the end before printing, so values are printed in reverse sequence order. No next fields are changed. There are n simultaneously pending frames at peak, giving Theta(n) auxiliary stack space in the ordinary runtime model. Reverse output is not a reversed data structure.','Reverse output; 0 link writes; Theta(n) stack',origin='Independent reconstruction of Stanford CS106B Handout 21 reverse-print routine')
q('Floyd meeting with a long prefix','Use standard Floyd complete-iteration comparisons with prefix length 13 and cycle length 5. Find meeting iteration and slow’s cycle offset.',r'The first positive multiple of 5 at least 13 is 15. Slow’s offset is $(15-13)\bmod5=2$. Detection makes 15 slow and 30 fast link advances. Resetting one cursor finds entry after 13 simultaneous one-link steps. An initial equality at head is not counted.','15; offset 2',check=dict(kind='floyd',mu=13,lam=5))
q('A pure cycle','Head already lies on a cycle of length 7. Under the same Floyd convention, does detection take zero iterations?',r'No. Initial equality of head handles is ignored. Slow and fast first collide after seven complete iterations, the smallest positive multiple of seven. The reset phase needs zero steps because head is the entry. Detection and entry discovery have different counts.','7 detection iterations; 0 reset steps',check=dict(kind='floyd',mu=0,lam=7))
q('Faster does not preserve the reset proof','Slow moves one link and fast three. Let prefix length be 1 and cycle length 4. Show why standard reset fails even after a collision.',r'Collision requires $2t\equiv0\pmod4$, so t=2 suffices once both are in the cycle. Slow’s meeting offset is 1. After moving a reset head cursor one step to entry, the meeting cursor is at offset 2. Their separation remains 2 under equal-speed movement, so they never meet. Speed two is part of the entry proof.','Meeting at t=2; reset never aligns')
q('Cycle-length measurement','After obtaining a meeting node in a cycle, one cursor is held fixed and another advances until it returns. Why is a do-while style positive traversal needed?',r'The cursors begin equal. Testing equality before the first move and stopping would report length zero. Advance at least once, incrementing the count for each successor followed; the first positive return takes exactly lambda links. A self-cycle correctly gives length one.','Count the first positive return')
q('Indexed traversal sum','For n=300, traverse a singly linked list by independently computing get(i) from head for each i. Count links followed. Compare a retained cursor.',r'Independent searches cost $0+1+\cdots+299=44850$ links. A retained cursor needs 299 links between real nodes, or 300 if the final tail-to-null move is counted. State the convention before comparing exact counts. Both routines inspect 300 payloads; this does not make their pointer work equal.','44850 versus 299',check=dict(kind='indexed',n=300))
q('Nested traversal with cached metadata','A loop repeats r times and each repetition scans an n-node singly linked list with one cursor. Cached size is constant-time. Compare this with repeating a get(i)-based indexed scan.',r'One cursor scan costs Theta(n), so r scans cost Theta(rn). An indexed scan costs Theta(n²) because rank i requires i traversals; r such scans cost Theta(rn²). Cached size avoids a length traversal but does not create random access.','Theta(rn) versus Theta(rn²)')
q('Binary search comparisons versus pointer work','An array and a sorted singly linked list each perform O(log n) key comparisons. The list repeatedly obtains midpoint by get(mid) from global head. Must its total time be O(log n)?',r'No. For a search above all keys, midpoint ranks approach n, and Theta(log n) retrievals each traverse Theta(n) links, giving Theta(n log n) link work. If each shrinking subrange stores its own start and midpoint is reached by a local walk, the geometric walk lengths sum to O(n). Neither version matches constant-time array midpoint access.','Not necessarily; global-head version can be Theta(n log n)')
q('The kth node from the end','A 25-node list has no cached size. Find the sixth node from the end using the k-gap method. Count successor advances including tail-to-null moves.',r'Lead first advances six links. Then lead and lag advance together for 19 iterations. Total lead movement is 25 and lag movement 19, hence 44 links. The answer is zero-based rank 19. If k exceeded n, the initial lead phase would detect the invalid request.','44; rank 19',check=dict(kind='kth',n=25,k=6))
q('Which middle does the code return?','For length 8, initialize slow=fast=head and loop while fast and fast.next exist, advancing slow once and fast twice. Which rank is returned?',r'There are four iterations. Slow reaches rank 4, the second of the two middle ranks 3 and 4. For length 7 it would reach rank 3. A loop guard involving fast.next.next or a shifted initialization may choose the first middle, so “the middle” alone is underspecified.','Rank 4')
q('Stable linked merge with equal keys','Two disjoint sorted lists hold labeled values L=[2a,4a,4b] and R=[2b,4c]. Merge stably relative to L followed by R. Which comparison tie policy is needed?',r'Take from L when keys are equal. The result is [2a,2b,4a,4b,4c]. Taking R first yields [2b,2a,...], violating relative order for the equal-key elements of the concatenated input. Stability concerns identities, not only numeric sortedness.','Take left on equality')
q('Exact merge comparison extremes','Merge lists of positive lengths 9 and 6, stopping key comparisons as soon as one list is exhausted. Give minimum and maximum comparisons over possible sorted keys.',r'The minimum is min(9,6)=6: every value of the shorter list may precede all values of the longer. The maximum is 9+6−1=14, attainable by interleaving until only one element remains. Attaching a remaining suffix does not compare its keys again. Empty inputs would give zero comparisons and require a separate case.','6 through 14')
q('Shared-tail merge hazard','Sorted lists A and B share an actual tail node T. Is destructive ordinary merge safe merely because both input value sequences are sorted?',r'No. Ordinary destructive merge assumes disjoint node sets. T can be selected from one path while remaining reachable from the other, so later rewiring can link the same object twice or create a self-cycle. Test or guarantee disjointness, preserve immutable sharing, or construct fresh output nodes. Sortedness alone is insufficient.','No; disjointness is required')
q('Stable compaction exact writes','Keep nonnegative values from [-2,5,0,-1,8,-3,4]. The compaction algorithm tests each element once and assigns every survivor to the write cursor even when it is already in place. Count tests and assignments and give the live prefix.',r'There are seven predicate tests and four surviving values: 5,0,8,4. Thus four payload assignments produce that live prefix. Write never exceeds read, so no unread value is lost. The old suffix is outside logical length; reference cleanup would add assignments if requested.','7 tests; 4 writes; [5,0,8,4]')
q('A left rotation with cached tail','For a length-17 singly linked list with cached size and tail, left-rotate by 40. Find normalized k, cut rank, and links traversed to reach the cut from head.',r'Normalize k=40 mod17=6. New tail is old rank 5; reaching it takes five next traversals. Save its successor as new head, connect old tail to old head, and set newTail.next=null. This performs two next-field writes after searching. If k=0, no cut or rewiring is needed.','k=6; cut rank 5; 5 traversals')
q('Intersection is identity, not equality','Two acyclic lists have identical numeric suffixes stored in separately allocated nodes. Will the two-switch cursor intersection algorithm report that suffix as an intersection?',r'No. It compares node identities; equal payloads in distinct nodes are not shared storage. Both cursors eventually reach null if there is no shared node. Value equality can be tested separately, but it answers a different question. The switching argument also assumes no cycles and no concurrent mutation.','No shared-node intersection')
q('Node alignment model','Payload is 13 bytes, each pointer is eight bytes, and node alignment is eight. Ignore headers. Find singly and doubly linked node sizes and storage for 100 real nodes plus one sentinel.',r'Singly linked raw size is 21, rounded to 24. Doubly linked raw size is 29, rounded to 32. The 101-node totals are 2424 and 3232 bytes. Treating alignment as a constant extra eight bytes rather than rounding is incorrect. Array element alignment can require its own separate stride assumption.','24,32; 2424,3232 bytes')
q('Offset block occupancy','A scan begins at slot offset 5 in a cache block of 16 slots and reads 100 consecutive slots. How many distinct blocks are touched?',r'The span ends after 105 slots measured from the beginning of the first block. Hence blocks touched are ceil(105/16)=7. Ceil(100/16)=7 happens to agree here, but with 12 slots from offset 5 the correct answer is 2 while ignoring offset gives 1. The question counts distinct blocks, not a hardware miss prediction with reuse.','7',check=dict(kind='blocks',n=100,r=5,L=16))
q('Workload with supplied handles','A workload contains n random rank lookups and n deletions at valid supplied node handles. Compare arrays and doubly linked lists; give a condition under which neither simple choice is obviously best.',r'Arrays perform rank lookups in Theta(n) total but stable deletions can cost Theta(n²). Doubly linked lists perform known-node deletions in Theta(n) total but rank lookups can cost Theta(n²). A workload mixing both capabilities may justify an augmented tree or index; the question provides no dominance ratio or ordering that selects one simple representation universally.','Both can incur quadratic total work')
q('Sparse outer-product support','Over real numbers, vectors of lengths 50 and 80 have 7 and 9 nonzero entries. How many nonzero entries does their outer product have? How many scalar slots does dense factor storage use?',r'Every nonzero entry of one factor pairs with every nonzero entry of the other, yielding 7·9=63 nonzeros. Dense factor storage uses 50+80=130 scalar slots; explicit dense matrix storage uses 4000. The product-support statement depends on a field without zero divisors, not an arbitrary ring.','63; 130',check=dict(kind='support',x=7,y=9))
q('Rank-one addition counterexample','Show why representing every matrix as a single pair of vectors is not closed under arbitrary addition.',r'Take two 2×2 matrices with single nonzeros at (0,0) and (1,1), both equal to one. Each is rank one. Their sum is the identity matrix, of rank two, and cannot equal one outer product because all columns of a nonzero outer product are scalar multiples of one vector. A general matrix ADT needs a broader representation.','Two rank-one matrices can sum to rank two')
q('A general orthogonal-list requirement','A sparse matrix must support row and column traversal without scanning all entries for either operation. Explain the two-link requirement and its overhead.',r'Each nonzero participates in two independent ordered chains: its row and its column. Store right and down links with row/column/value coordinates and appropriate headers. A row-only list of lists exposes no direct column chain. If pointers are eight bytes, the two traversal links alone cost 16 bytes per nonzero before coordinates, values, and alignment.','Right and down adjacency, plus headers')
q('Sorted insertion and duplicate semantics','An iterative routine refuses an existing equal key; a recursive routine inserts before the first key greater than or equal to the new key. Are they equivalent? Give a distinguishing input.',r'Insert key 4 into [2,4,6]. The iterative set-style routine keeps [2,4,6]; the recursive routine produces [2,4,4,6]. Thus duplicate policy is part of the interface. If allocation happens before detecting a duplicate, rejected storage must be released to avoid a leak. Correct sorted order alone does not establish equivalence.','They differ on duplicate insertion',origin='Independent reconstruction and correction of Stanford CS106B Handout 21 duplicate-policy contrast')
q('Deep-copy versus pointer-copy append','An array stores pointers to variable-length strings. During growth, it copies pointers, not string contents. What controls resize complexity? What changes if it deep-copies each string?',r'Pointer-copy growth moves n word-sized slots, so cost is Theta(n). If strings have lengths ell_i and each must be duplicated, copying costs Theta(sum ell_i), plus pointer work. An operation-count theorem must specify the copied unit. Large values referenced by pointers do not automatically enlarge a slot-copy cost.','Theta(n) pointer copies versus Theta(sum lengths) deep copies')
q('Searching before constant unlink','A doubly linked list contains n unique keys but no search index. Delete by a given key value. Is the operation worst-case constant because node unlinking is constant?',r'Locating the key can inspect n nodes, so deletion by value is Theta(n) worst case even though unlinking a located node is constant. A valid supplied node handle removes that search. Distinguish the operation argument type from the chosen pointer update.','Theta(n) worst case')
q('Destruction order safety','Why must iterative deletion save next before releasing a node? Does reading a deallocated next field become safe if its old bits appear unchanged?',r'Once storage is released, the program no longer owns a live node at that address; accessing its fields is invalid under the allocation model and may be undefined in a systems language. Save successor while the node is alive, release the node, then advance through the saved handle. Observing unchanged bits does not restore object lifetime.','Save successor before release',origin='Independent reconstruction of Stanford CS106B Handout 21 destruction routine')
q('Empty and singleton reversal','Specify the correct postconditions for reversing an empty list and a singleton list with cached tail.',r'For empty input, head and tail remain null and size stays zero; the loop performs no link writes. For singleton X, X.next becomes null, head and tail both remain X, and size stays one. The general routine may perform one next write even though the value does not change. A cached tail becomes the saved old head for every nonempty input.','Empty: 0 writes; singleton: 1 next write')
q('A splice into its own interior','A range B through D in a circular list is to be moved after C. Why cannot a generic six-write cross-list splice be applied without a precondition?',r'C lies inside the moved range, so its adjacency links are among the links being detached and reused. Treating it as an external destination can introduce a cycle disconnected from the sentinel or duplicate placement. Reject the request or define a no-op policy for interior destinations; ordinary same-list splice proofs require the destination outside the range and handle adjacency separately.','Interior destination violates the splice precondition')
q('General fast-speed meeting congruence','For fast speed r>1 and cycle length lambda, derive the period of meeting times once both pointers are on the cycle. Do not infer entry-reset validity.',r'Equality requires (r−1)t to be divisible by lambda. Dividing by d=gcd(r−1,lambda), the reduced coefficients are coprime, so t must be a multiple of lambda/d. The first permitted meeting must also be positive and at least mu. This detects collision but does not force t divisible by lambda when d>1; standard reset may fail.','Period lambda/gcd(r−1,lambda)')
q('Worst cost with a growth-triggering front insertion','A length-64 capacity-64 array doubles then stably inserts a new value at rank zero. Count old-slot copies if the implementation first copies to identical ranks then shifts in the new buffer.',r'Growth copies 64 old slots. Stable insertion then shifts the same 64 elements one position right. There is one new-value write, giving 129 total element writes. A fused resize could copy each old element directly to its final shifted position and use 65 writes, but that is a different implementation. Exact questions must specify whether copying is fused.','128 old-slot copies; 129 total writes')
q('Fused resizing insertion','Resize a full n-slot array while inserting at rank i. Show an implementation using n old-slot copies rather than n+(n−i) copies.',r'Allocate the new buffer. Copy old positions below i to unchanged ranks; copy positions at or above i directly to rank j+1; write x at i. Every old element is copied once, for n copies plus one new write. The original buffer remains read-only until replacement, so overlapping-copy ordering is unnecessary. Nonresizing insertion still has n−i shifts.','n+1 element writes')
q('Unrolled-list tradeoff','A sequence stores contiguous blocks of B elements in a linked chain. Locating a rank scans block links; insertion can shift within one block. Derive the balancing scale for cost O(n/B+B), ignoring splits and rounding.',r'There are roughly n/B blocks, giving O(n/B) link work; moving within a block costs O(B). Balancing n/B and B gives B≈sqrt(n), with O(sqrt(n)) combined work. This is a simplified model, not a full implementation proof: block occupancy, splits, size metadata, and changing n need separate invariants.','B≈sqrt(n); simplified O(sqrt(n))')
q('Stable deduplication of a sorted array','A sorted array of length n is compacted to one representative of each of k distinct values. Derive comparisons and worst retained writes for a one-pass algorithm that keeps the first value.',r'Compare each later value against the last kept representative, yielding n−1 equality comparisons for n>0. Each new distinct value may require one write, so there are k retained assignments if the initial value is assigned too, or at most k−1 if it is already kept in place. Empty input requires no first-element access. Sorting beforehand is not free and is not part of this pre-sorted problem.','n−1 comparisons; k or at most k−1 writes under the specified convention')
q('Invalid handles after buffer movement','A caller retains a pointer to A[3] and the dynamic array resizes into a different buffer. The logical value remains at rank 3. Is the old pointer valid?',r'No guarantee exists: the old buffer is released, so the saved physical address may dangle. A saved logical index can be re-resolved in the new buffer, provided mutations have not changed the intended position. Stable object handles require indirection or a different representation. Logical sequence preservation does not preserve backing-store addresses.','Old physical pointer may dangle')
q('Adversarial versus random amortization','An adversary chooses the times of appends and last-element deletions for a doubling/quarter-shrinking array. Can it invalidate the potential-method bound merely by knowing the current capacity?',r'No, for operations satisfying the fixed policy and cost model. The potential bound applies to each legal transition and telescopes for every sequence, including adversarial choices. It can create expensive individual updates but cannot force superlinear total capacity-management work. Changing to middle operations, expensive destructors, or a different shrink threshold changes the premises.','Bound holds for every legal append/delete-last sequence')
q('Stable deletion expected cost','Delete a uniformly selected live rank from length 31. Count shifts only. Derive the expectation without assuming independent movement events.',r'Rank i shifts 30−i elements. Average over i=0,…,30: (30+29+…+0)/31=15. Equivalently, sum the probability that each later element must move. Linearity of expectation does not require independence. One deletion can still shift 30 elements.','15')
q('Array prefix versus list prefix copy','Copy the first k elements of a sequence into a fresh output. Compare an array, a cursor-based list scan, and k independent list get(i) calls.',r'An array copies k slots in Theta(k). A list cursor reads k payloads and follows at most k links, also Theta(k). Independent get(i) calls add k(k−1)/2 links and k payload reads, giving Theta(k²). Allocation and deep-copy payload costs are excluded unless stated.','Theta(k), Theta(k), Theta(k²)')
q('Circular singly linked tail deletion','A circular singly linked list stores only tail, with head=tail.next. Does circularity make deleting tail constant time?',r'No. Its predecessor still has only a forward next link. For n>1, traverse from head until a node points to tail, then reconnect it to head and update tail. This is Theta(n). Circularity makes head accessible from tail but does not supply predecessor links. The singleton case is constant and sets the list empty.','Theta(n) for n>1')
q('Overflow in address arithmetic','Why is the formula B+b(i−L) not a sufficient safety proof for array access in a real implementation?',r'One must also establish index bounds, multiplication/addition representability, allocated object extent, and an appropriate stride. Even a mathematically valid rank can overflow a narrow machine integer if unchecked. The chapter’s RAM formulas assume these conditions; code handling external sizes must validate them. Address algebra is not a license to dereference arbitrary computed addresses.','Bounds, representability, and allocated extent are also required')
q('Caching the predecessor in a scan','A singly linked list is scanned once and selected nodes are removed. Explain how retaining the predecessor avoids repeated searches and how the cursor updates after a removal.',r'Keep predecessor p and current v=p.next, starting with a head sentinel. If v survives, advance p=v. If v is removed, set p.next=v.next and keep p unchanged; the next candidate is its new successor. Each node is examined once. Searching from head for each victim can produce quadratic work. Tail and size must be updated during deletions.','One-pass linear filtering')
q('Outer products over a ring','Does nnz(ab^T)=nnz(a)nnz(b) hold over integers modulo six? Give a counterexample.',r'No. In Z/6Z, 2 and 3 are nonzero but their product is 0. Taking one-element vectors a=(2), b=(3) gives support counts one and one but a zero outer product. The real-number proof uses absence of zero divisors. Algebraic domain assumptions can change a data-representation count.','Counterexample 2·3=0 mod6')
# Compound quantitative instances, with explicit derivations rather than one-step drills.
for m,c0,g in [(75,1,2),(121,3,2),(82,2,3),(1001,4,2)]:
    C=c0;copies=0;worst=1
    while C<m:copies+=C;worst=C+1;C*=g
    q(f'Growth accounting and memory, length {m}',f'A full-buffer growth factor {g} array starts empty at capacity {c0}. Append {m} four-byte slots. Compute copy work, total writes, final slack, and peak two-buffer bytes.',f'Capacities form a geometric sequence ending at {C}. Earlier capacities sum to {copies}, using $(C_{{final}}-C_0)/(g-1)$. Appended-slot writes are {m}, so total is {m+copies}. Final unused slots are {C-m}. The last growth simultaneously holds capacities {C//g} and {C}, giving {(C+C//g)*4} bytes; this is the peak under separate allocation. Largest append costs {worst} writes. Final memory alone is smaller.',f'{copies}; {m+copies}; {C-m}; {(C+C//g)*4}',check=dict(kind='growthcompound',m=m,c0=c0,g=g,b=4))
for n,i,k in [(20,4,6),(33,11,7),(50,3,12),(27,20,5)]:
    shifts=k*(n-i)+k*(k-1)//2
    q(f'Batch insertion at a fixed rank {i}',f'Length is {n}, ample capacity exists. Insert {k} new values one by one at the same rank {i}, preserving order at each step. Count shifts, total writes, and final order of the newly inserted values x1,…,x{k}.',f'Before insertion t (zero-based), length is {n}+t and shifts are {n-i}+t. Their sum is ${k}({n}-{i})+{k}({k}-1)/2={shifts}$. New-slot writes add {k}, giving {shifts+k}. Since every new insertion precedes the previous ones at rank {i}, the new block is x{k},…,x1, not insertion order. Resizing is excluded by ample capacity.',f'{shifts}; {shifts+k}; reversed new block',check=dict(kind='batch',n=n,i=i,k=k))
for mu,lam in [(6,7),(17,6),(24,4),(0,9)]:
    t=lam*max(1,math.ceil(mu/lam));cost=3*t+2*mu+lam
    q(f'Full cycle-analysis cost ({mu},{lam})',f'A reachable cycle has prefix {mu} and length {lam}. Under standard Floyd complete-iteration comparisons, count detection iterations, entry-phase moves, cycle-length moves, and total successor advances across all three phases.',f'The smallest positive multiple of {lam} at least {mu} is {t}. Detection advances one and two links per iteration, for {3*t} links. Reset-to-entry advances two cursors for {mu} steps, for {2*mu} links. One full lap measures length in {lam} moves. Total is {cost}. This excludes redundant guard reads; initial handle equality is not a collision.',f'{t}; {2*mu}; {lam}; {cost}',check=dict(kind='cyclecompound',mu=mu,lam=lam))
for n,k,r,L in [(64,9,3,8),(101,17,7,16),(200,50,1,32),(45,45,6,8)]:
    copies=n-k;blocks=math.ceil((r+n)/L)
    q(f'Choosing a traversal for n={n}',f'A {n}-element sequence has no cached list length. Find the {k}th element from the end using a list gap scan, or scan an array beginning at block offset {r} with {L} slots per block. Compute list successor moves and array blocks touched. Explain why these counts have different units.',f'Gap scan lead movement is {n}; lag movement is {n-k}, so successor advances total {2*n-k}. The array scan touches $\\lceil({r}+{n})/{L}\\rceil={blocks}$ distinct blocks. These are not directly comparable runtime units: block fetch latency and pointer-chasing placement matter. With cached list length, reaching rank {n-k} would need only {n-k} traversals.',f'{2*n-k} links; {blocks} blocks',check=dict(kind='traversecompound',n=n,k=k,r=r,L=L))
